for (int i = 1; i < n; i++) {        // 불변식: a[0..i-1]은 정렬되어 있다
    int key = a[i], j = i - 1;
    while (j >= 0 && a[j] > key) {
        a[j + 1] = a[j];             // 한 칸 밀기
        j--;
    }
    a[j + 1] = key;
}

